class DragonflyMemory:
    def __init__(self, host: str, port: int, password: str, db: int = 0):
        self.client = redis.Redis(host=host, port=port, password=password, db=db, decode_responses=True)

    def store(self, key: str, value: Any, expire: Optional[int] = None):
        self.client.set(key, json.dumps(value), ex=expire)

    def retrieve(self, key: str) -> Optional[Any]:
        data = self.client.get(key)
        return json.loads(data) if data else None

    def append_to_list(self, key: str, value: Any):
        self.client.rpush(key, json.dumps(value))

    def get_list(self, key: str) -> List[Any]:
        items = self.client.lrange(key, 0, -1)
        return [json.loads(item) for item in items]

    def delete(self, key: str):
        self.client.delete(key)

    def exists(self, key: str) -> bool:
        return bool(self.client.exists(key))

class AIModelOrchestrator:
    def __init__(self):
        self.cerebras = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))
        self.bedrock = AnthropicBedrock(aws_access_key=os.environ.get("AWS_ACCESS_KEY"), aws_secret_key=os.environ.get("AWS_SECRET_KEY"), aws_region="us-east-1")
        self.grok_api_key = os.environ.get("GROK_API_KEY")
        self.grok_base_url = ""

    def call_cerebras(self, messages: List[Dict], model: str = "qwen-3-235b-a22b-thinking-2507", max_tokens: int = 131072, temperature: float = 0.7, stream: bool = False):
        return self.cerebras.chat.completions.create(model=model, messages=messages, max_tokens=max_tokens, temperature=temperature, stream=stream)

    def call_gpt_oss_120b(self, messages: List[Dict], max_tokens: int = 131072, temperature: float = 0.7):
        return self.cerebras.chat.completions.create(model="gpt-oss-120b", messages=messages, max_tokens=max_tokens, temperature=temperature)

    def call_bedrock_claude(self, messages: List[Dict], max_tokens: int = 65536, temperature: float = 0.7):
        anthropic_messages = []
        system_message = None
        for msg in messages:
            if msg['role'] == 'system':
                system_message = msg['content']
            else:
                anthropic_messages.append({"role": msg['role'], "content": msg['content']})
        kwargs = {"model": "us.anthropic.claude-sonnet-4-5-20250929-v1:0", "messages": anthropic_messages, "max_tokens": max_tokens, "temperature": temperature}
        if system_message:
            kwargs['system'] = system_message
        return self.bedrock.messages.create(**kwargs)

    def call_grok(self, messages: List[Dict], max_tokens: int = 65536, temperature: float = 0.7, stream: bool = False):
        headers = {"Authorization": f"Bearer {self.grok_api_key}", "Content-Type": "application/json"}
        payload = {"model": "grok-4-fast", "messages": messages, "max_tokens": max_tokens, "temperature": temperature, "stream": stream}
        response = requests.post(f"{self.grok_base_url}/chat/completions", headers=headers, json=payload, stream=stream)
        if response.status_code != 200:
            raise Exception(f"Grok API error: {response.status_code} - {response.text}")
        return response

class ExaResearchEngine:
    def __init__(self, api_key: str):
        self.client = Exa(api_key=api_key)

    def neural_search(self, query: str, num_results: int = 100, text: bool = True, highlights: bool = True, livecrawl: str = "always"):
        return self.client.search_and_contents(query=query, num_results=num_results, type="neural", text=text, highlights=highlights, livecrawl=livecrawl)

    def keyword_search(self, query: str, num_results: int = 100, text: bool = True):
        return self.client.search_and_contents(query=query, num_results=num_results, type="keyword", text=text)

    def find_similar(self, url: str, num_results: int = 100, text: bool = True):
        return self.client.find_similar_and_contents(url=url, num_results=num_results, text=text, exclude_source_domain=True)

    def get_contents(self, urls: List[str], text: bool = True, highlights: bool = True, subpages: int = 9, livecrawl: str = "preferred"):
        return self.client.get_contents(ids=urls, text=text, highlights=highlights, subpages=subpages, livecrawl=livecrawl)

    def research_task(self, instructions: str, model: str = "exa-research-pro"):
        task = self.client.research.create_task(model=model, instructions=instructions)
        return self.client.research.poll_until_finished(task)

class AutonomousDeepSearchAgent:
    def __init__(self, session_id: str):
        self.session_id = session_id
        self.models = AIModelOrchestrator()
        self.exa = ExaResearchEngine(api_key=os.environ.get("EXA_API_KEY"))
        self.memory_db = DragonflyMemory(host=os.environ.get("DRAGONFLY_HOST_1", "localhost"), port=int(os.environ.get("DRAGONFLY_PORT_1", 6379)), password=os.environ.get("DRAGONFLY_PASSWORD_1", ""))
        self.cache_db = DragonflyMemory(host=os.environ.get("DRAGONFLY_HOST_2", "localhost"), port=int(os.environ.get("DRAGONFLY_PORT_2", 6380)), password=os.environ.get("DRAGONFLY_PASSWORD_2", ""))
        self.event_queue = Queue()
        self.max_iterations = 60
        self.total_sources = 0
        self.decision_log = []

    def emit_event(self, event_type: str, data: Dict):
        event = {"type": event_type, "data": data, "timestamp": datetime.utcnow().isoformat()}
        self.event_queue.put(event)
        self.memory_db.append_to_list(f"session:{self.session_id}:events", event)

    def think(self, context: str, question: str) -> Dict:
        self.emit_event("thinking", {"context_preview": context[:200], "question": question})
        messages = [{"role": "system", "content": "You are an expert reasoning engine. Analyze the context deeply and provide strategic insights."}, {"role": "user", "content": f"Context: {context}\n\nQuestion: {question}\n\nProvide your analysis as JSON with keys: reasoning, conclusion, next_actions"}]
        response = self.models.call_cerebras(messages=messages, model="qwen-3-235b-a22b-thinking-2507", max_tokens=131072)
        try:
            result = json.loads(response.choices[0].message.content)
        except:
            result = {"reasoning": response.choices[0].message.content, "conclusion": "Analysis complete", "next_actions": []}
        self.decision_log.append({"timestamp": datetime.utcnow().isoformat(), "question": question, "result": result})
        return result

    def decide_search_strategy(self, query: str, iteration: int, findings_so_far: List[Dict]) -> Dict:
        self.emit_event("decision_making", {"iteration": iteration, "query": query})
        context = f"Original query: {query}\nIteration: {iteration}/{self.max_iterations}\nFindings collected: {len(findings_so_far)}"
        decision = self.think(context, "What search strategy should I use next? Consider: neural search, keyword search, find_similar, get_contents with subpages, or deep research task. Respond with JSON: {strategy: str, reasoning: str, params: dict}")
        return decision

    def execute_search(self, strategy: str, params: Dict) -> List[Dict]:
        self.emit_event("executing_search", {"strategy": strategy, "params": params})
        results = []
        try:
            if strategy == "neural_search":
                response = self.exa.neural_search(query=params.get("query", ""), num_results=params.get("num_results", 100))
                results = [{"url": r.url, "title": r.title, "text": r.text, "highlights": getattr(r, 'highlights', []), "published_date": r.published_date} for r in response.results]
            elif strategy == "keyword_search":
                response = self.exa.keyword_search(query=params.get("query", ""), num_results=params.get("num_results", 100))
                results = [{"url": r.url, "title": r.title, "text": r.text, "published_date": r.published_date} for r in response.results]
            elif strategy == "find_similar":
                response = self.exa.find_similar(url=params.get("url", ""), num_results=params.get("num_results", 100))
                results = [{"url": r.url, "title": r.title, "text": r.text} for r in response.results]
            elif strategy == "get_contents":
                response = self.exa.get_contents(urls=params.get("urls", []), text=True, highlights=True, subpages=params.get("subpages", 9))
                results = [{"url": r.url, "title": getattr(r, 'title', ''), "text": r.text, "highlights": getattr(r, 'highlights', [])} for r in response.results]
            elif strategy == "research_task":
                response = self.exa.research_task(instructions=params.get("instructions", ""), model="exa-research-pro")
                results = [{"research_output": str(response)}]
            self.total_sources += len(results)
            self.emit_event("search_complete", {"strategy": strategy, "results_count": len(results)})
        except Exception as e:
            self.emit_event("error", {"message": f"Search error: {str(e)}", "strategy": strategy})
        return results

    def analyze_source(self, source: Dict, research_goal: str) -> Dict:
        cache_key = f"analysis:{hash(source.get('url', '') + research_goal)}"
        if self.cache_db.exists(cache_key):
            return self.cache_db.retrieve(cache_key)
        self.emit_event("analyzing_source", {"url": source.get("url", ""), "title": source.get("title", "")})
        text_content = source.get("text", "")[:50000]
        messages = [{"role": "system", "content": "You are an expert research analyst. Extract key insights, facts, statistics, and quotes relevant to the research goal."}, {"role": "user", "content": f"Research Goal: {research_goal}\n\nSource Title: {source.get('title', '')}\nSource Text: {text_content}\n\nProvide analysis as JSON with: key_insights (list), important_facts (list), quotes (list), relevance_score (0-100)"}]
        response = self.models.call_bedrock_claude(messages=messages, max_tokens=65536)
        try:
            analysis = json.loads(response.content[0].text)
        except:
            analysis = {"key_insights": [response.content[0].text], "important_facts": [], "quotes": [], "relevance_score": 50}
        analysis["source_url"] = source.get("url", "")
        analysis["source_title"] = source.get("title", "")
        self.cache_db.store(cache_key, analysis, expire=86400)
        return analysis

    def synthesize_findings(self, all_analyses: List[Dict], iteration: int) -> Dict:
        self.emit_event("synthesizing", {"analyses_count": len(all_analyses), "iteration": iteration})
        context = json.dumps(all_analyses, indent=2)[:80000]
        messages = [{"role": "system", "content": "You are a master synthesizer. Combine all research findings into coherent insights."}, {"role": "user", "content": f"Synthesize these research findings (iteration {iteration}):\n{context}\n\nProvide JSON with: main_themes (list), emerging_patterns (list), knowledge_gaps (list), confidence_level (0-100)"}]
        response = self.models.call_gpt_oss_120b(messages=messages, max_tokens=131072)
        try:
            synthesis = json.loads(response.choices[0].message.content)
        except:
            synthesis = {"main_themes": [response.choices[0].message.content], "emerging_patterns": [], "knowledge_gaps": [], "confidence_level": 50}
        self.memory_db.store(f"session:{self.session_id}:synthesis:{iteration}", synthesis)
        return synthesis

    def should_continue_research(self, synthesis: Dict, iteration: int) -> bool:
        if iteration >= self.max_iterations:
            return False
        decision = self.think(json.dumps(synthesis), f"Should I continue researching? Consider confidence level, knowledge gaps, and iteration {iteration}/{self.max_iterations}. Respond JSON: {{continue: bool, reasoning: str}}")
        return decision.get("conclusion", {}).get("continue", True) if isinstance(decision.get("conclusion"), dict) else iteration < 30

    def generate_subsection(self, topic: str, findings: List[Dict], word_target: int) -> str:
        self.emit_event("generating_subsection", {"topic": topic, "word_target": word_target})
        context = json.dumps(findings, indent=2)[:60000]
        messages = [{"role": "system", "content": f"You are an expert writer. Write a detailed {word_target}-word section on the given topic using the research findings."}, {"role": "user", "content": f"Topic: {topic}\n\nResearch Findings:\n{context}\n\nWrite a comprehensive, well-structured section with subheadings, citations, and deep analysis."}]
        response = self.models.call_grok(messages=messages, max_tokens=65536, stream=True)
        full_text = ""
        for line in response.iter_lines():
            if line:
                line_str = line.decode('utf-8')
                if line_str.startswith('data: '):
                    data_str = line_str[6:]
                    if data_str == '[DONE]':
                        break
                    try:
                        data = json.loads(data_str)
                        if 'choices' in data and len(data['choices']) > 0:
                            delta = data['choices'][0].get('delta', {})
                            if 'content' in delta:
                                chunk = delta['content']
                                full_text += chunk
                                self.event_queue.put({"type": "report_chunk", "data": {"chunk": chunk}, "timestamp": datetime.utcnow().isoformat()})
                    except:
                        pass
        return full_text

    def create_report_structure(self, all_findings: List[Dict], query: str) -> Dict:
        self.emit_event("creating_structure", {"findings_count": len(all_findings)})
        context = json.dumps([f for f in all_findings[:100]], indent=2)[:70000]
        messages = [{"role": "system", "content": "You are an expert report architect. Design a comprehensive 20-30 page report structure."}, {"role": "user", "content": f"Original Query: {query}\n\nResearch Findings Summary:\n{context}\n\nCreate a detailed report structure as JSON with: title, executive_summary_points (list), sections (list of {{title, subsections (list), word_target}}), total_word_target (20000-30000)"}]
        response = self.models.call_bedrock_claude(messages=messages, max_tokens=65536)
        try:
            structure = json.loads(response.content[0].text)
        except:
            structure = {"title": query, "executive_summary_points": ["Research findings"], "sections": [{"title": "Main Findings", "subsections": ["Overview", "Details"], "word_target": 5000}], "total_word_target": 25000}
        return structure

    def run_autonomous_research(self, query: str):
        self.emit_event("research_started", {"query": query, "session_id": self.session_id, "max_iterations": self.max_iterations})
        all_findings = []
        all_analyses = []
        iteration = 0
        research_active = True
        while research_active and iteration < self.max_iterations:
            iteration += 1
            self.emit_event("iteration_start", {"iteration": iteration, "findings_count": len(all_findings)})
            strategy_decision = self.decide_search_strategy(query, iteration, all_findings)
            strategy = strategy_decision.get("conclusion", {}).get("strategy", "neural_search") if isinstance(strategy_decision.get("conclusion"), dict) else "neural_search"
            params = strategy_decision.get("conclusion", {}).get("params", {"query": query, "num_results": 100}) if isinstance(strategy_decision.get("conclusion"), dict) else {"query": query, "num_results": 100}
            search_results = self.execute_search(strategy, params)
            for source in search_results:
                analysis = self.analyze_source(source, query)
                all_analyses.append(analysis)
                all_findings.append({"source": source, "analysis": analysis, "iteration": iteration})
            if iteration % 5 == 0 or iteration >= 10:
                synthesis = self.synthesize_findings(all_analyses, iteration)
                research_active = self.should_continue_research(synthesis, iteration)
            time.sleep(1)
        self.emit_event("research_complete", {"total_iterations": iteration, "total_sources": self.total_sources, "total_analyses": len(all_analyses)})
        return all_findings, all_analyses

    def generate_full_report(self, query: str):
        start_time = time.time()
        self.emit_event("agent_started", {"query": query, "timestamp": datetime.utcnow().isoformat()})
        all_findings, all_analyses = self.run_autonomous_research(query)
        self.emit_event("report_generation_started", {"findings_count": len(all_findings)})
        structure = self.create_report_structure(all_analyses, query)
        report_parts = [f"# {structure.get('title', query)}\n\n"]
        report_parts.append(f"**Research Session**: {self.session_id}\n")
        report_parts.append(f"**Generated**: {datetime.utcnow().isoformat()}\n")
        report_parts.append(f"**Total Sources Analyzed**: {self.total_sources}\n\n")
        report_parts.append("## Executive Summary\n\n")
        for point in structure.get('executive_summary_points', []):
            report_parts.append(f"- {point}\n")
        report_parts.append("\n")
        for section in structure.get('sections', []):
            report_parts.append(f"## {section['title']}\n\n")
            for subsection in section.get('subsections', []):
                word_target = section.get('word_target', 5000) // len(section.get('subsections', [1]))
                subsection_text = self.generate_subsection(f"{section['title']} - {subsection}", all_analyses, word_target)
                report_parts.append(f"### {subsection}\n\n")
                report_parts.append(subsection_text + "\n\n")
        report_parts.append("## References\n\n")
        unique_sources = {a['source_url']: a['source_title'] for a in all_analyses if 'source_url' in a}
        for idx, (url, title) in enumerate(unique_sources.items(), 1):
            report_parts.append(f"{idx}. [{title}]({url})\n")
        report_parts.append(f"\n\n## Research Metadata\n\n")
        report_parts.append(f"- **Total Research Time**: {int(time.time() - start_time)} seconds\n")
        report_parts.append(f"- **Decision Log Entries**: {len(self.decision_log)}\n")
        full_report = "".join(report_parts)
        self.memory_db.store(f"session:{self.session_id}:final_report", full_report)
        self.emit_event("report_complete", {"report_length": len(full_report), "elapsed_time": int(time.time() - start_time)})
        return full_report

agent_sessions = {}

@app.route('/api/start', methods=['POST'])
def start_research():
    data = request.json
    query = data.get('query', '')
    if not query:
        return jsonify({"error": "Query required"}), 400
    session_id = str(uuid.uuid4())
    agent = AutonomousDeepSearchAgent(session_id=session_id)
    agent_sessions[session_id] = agent
    def run_agent():
        try:
            agent.generate_full_report(query)
        except Exception as e:
            agent.emit_event("error", {"message": str(e)})
    thread = threading.Thread(target=run_agent, daemon=True)
    thread.start()
    return jsonify({"session_id": session_id, "status": "started"})

@app.route('/api/stream/<session_id>', methods=['GET'])
def stream_events(session_id):
    if session_id not in agent_sessions:
        return jsonify({"error": "Session not found"}), 404
    agent = agent_sessions[session_id]
    def generate():
        while True:
            try:
                event = agent.event_queue.get(timeout=60)
                yield f"data: {json.dumps(event)}\n\n"
                if event['type'] in ['report_complete', 'error']:
                    break
            except:
                yield f"data: {json.dumps({'type': 'heartbeat', 'data': {}, 'timestamp': datetime.utcnow().isoformat()})}\n\n"
    return Response(generate(), mimetype='text/event-stream', headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'})

@app.route('/api/report/<session_id>', methods=['GET'])
def get_report(session_id):
    if session_id not in agent_sessions:
        return jsonify({"error": "Session not found"}), 404
    agent = agent_sessions[session_id]
    report = agent.memory_db.retrieve(f"session:{session_id}:final_report")
    if not report:
        return jsonify({"error": "Report not ready"}), 404
    return jsonify({"report": report, "session_id": session_id})

@app.route('/api/status/<session_id>', methods=['GET'])
def get_status(session_id):
    if session_id not in agent_sessions:
        return jsonify({"error": "Session not found"}), 404
    agent = agent_sessions[session_id]
    events = agent.memory_db.get_list(f"session:{session_id}:events")
    return jsonify({"session_id": session_id, "total_events": len(events), "latest_events": events[-10:] if events else []})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy", "timestamp": datetime.utcnow().isoformat()})

